const items = $input.all();

const quarterFocus = {
  1: 'Career Assessment & Objectives',
  2: 'Skill & Leadership Development',
  3: 'Skill & Leadership Development (continued)',
  4: 'Measure of Success & Culture Impact'
};

const GRACE_WEEKS = 1;
const REMINDER_WEEKS = 3;
const ESCALATION_WEEK = 4;

function weeksSince(openedAt, now = new Date()) {
  if (!openedAt) return 1;
  const d = new Date(openedAt);
  if (Number.isNaN(d.getTime())) return 1;
  const days = Math.max(0, Math.floor((now - d) / 86400000));
  return Math.floor(days / 7) + 1;
}

function quarterBounds(cohortStartDate, quarterNo) {
  const start = new Date(cohortStartDate);
  if (Number.isNaN(start.getTime())) return { start: null, end: null };

  const q = Number.isFinite(quarterNo) ? quarterNo : 1;
  const qOffsetDays = Math.max(0, q - 1) * 91;

  const qStart = new Date(start);
  qStart.setDate(qStart.getDate() + qOffsetDays);

  const qEnd = new Date(qStart);
  qEnd.setDate(qEnd.getDate() + 91);

  return { start: qStart, end: qEnd };
}

return items.map(item => {
  const d = item.json;
  const quarter = parseInt(d.current_quarter);
  const status = d.cycle_status;
  const cp1Done = !!d.cp1_mentee_completed && !!d.cp1_mentor_completed;
  const cp2Done = !!d.cp2_mentee_completed && !!d.cp2_mentor_completed;

  let action = 'skip';
  let targetCheckpointNo = null;
  let checkpointWeek = null;

  if (status === 'no_cycle') {
    action = quarter === 1 ? 'week1_goals' : 'week1_no_goals';
    targetCheckpointNo = 1;
    checkpointWeek = 1;
  } else if (status === 'pending' || status === 'escalated') {
    if (!cp1Done) {
      targetCheckpointNo = 1;
      checkpointWeek = weeksSince(d.cp1_opened_at || d.cycle_created_at);
    } else if (!cp2Done) {
      targetCheckpointNo = 2;
      const cp2Opened = (d.cp1_mentee_completed_at && d.cp1_mentor_completed_at)
        ? (new Date(d.cp1_mentee_completed_at) > new Date(d.cp1_mentor_completed_at)
            ? d.cp1_mentee_completed_at
            : d.cp1_mentor_completed_at)
        : d.cp2_row_created_at;
      checkpointWeek = weeksSince(cp2Opened || d.cycle_created_at);
    }

    if (targetCheckpointNo !== null) {
      if (checkpointWeek <= GRACE_WEEKS) action = 'skip';
      else if (checkpointWeek <= REMINDER_WEEKS) action = 'reminder';
      else if (checkpointWeek >= ESCALATION_WEEK) action = 'escalate_and_remind';
    }
  }

  const qBounds = quarterBounds(d.cohort_start_date, quarter);

  return {
    json: {
      ...d,
      _action: action,
      _target_checkpoint_no: targetCheckpointNo,
      _checkpoint_week: checkpointWeek,
      _quarter_start_at: qBounds.start ? qBounds.start.toISOString() : null,
      _quarter_end_at: qBounds.end ? qBounds.end.toISOString() : null,
      _quarterFocus: quarterFocus[d.current_quarter] || 'Development'
    }
  };
});

const items = $input.all();

function makeToken() {
  return [
    Math.random().toString(36).slice(2),
    Math.random().toString(36).slice(2),
    Date.now().toString(36)
  ].join('');
}

return items.map(item => {
  const expiry = new Date();
  expiry.setDate(expiry.getDate() + 30);

  const quarter = parseInt(item.json.current_quarter || item.json.quarter || 1);
  const hasMenteeQ1Goals = !!item.json.mentee_goals_submitted;

  return {
    json: {
      ...item.json,
      checkpoint_no: parseInt(item.json._target_checkpoint_no || 1),
      mentee_goal_token: quarter === 1 && !hasMenteeQ1Goals ? makeToken() : null,
      mentor_goal_token: makeToken(),
      token_expiry: expiry.toISOString()
    }
  };
});

const cycleRows = $input.all();
const tokenItems = $('Generate Goal Tokens').all();

// Build a lookup map from table_8 → cycle_id from table_9 Create Cycle results
// Create Cycle returns pair_id alongside cycle_id via RETURNING
const cycleMap = {};
for (const row of cycleRows) {
  if (row.json.pair_id && row.json.cycle_id) {
    cycleMap[row.json.pair_id] = row.json.cycle_id;
  }
}

return tokenItems.map(item => {
  const pair_id = item.json.pair_id;

  // Use the freshly created cycle_id if available,
  // fall back to the one already on the item (pre-existing cycle)
  const cycle_id = cycleMap[pair_id] || item.json.cycle_id;

  if (!cycle_id) {
    throw new Error(`No cycle_id found for pair_id ${pair_id} — cycle creation may have failed`);
  }

  return {
    json: {
      ...item.json,
      cycle_id
    }
  };
});

