function ratingField(name, labelText) {
  return `<div class="field">
    <label>${labelText}</label>
    <div class="scale-row">
      ${[1,2,3,4,5].map(n => `<label class="scale-opt"><input type="radio" name="${name}" value="${n}" required /><span>${n}</span></label>`).join('')}
    </div>
    <div class="scale-labels"><span>Poor</span><span>Excellent</span></div>
  </div>`;
}

function formSubmitScript() {
  return `
    document.getElementById('feedbackForm').addEventListener('submit', async function(e) {
      e.preventDefault();
      const btn = this.querySelector('button');
      btn.textContent = 'Submitting...';
      btn.disabled = true;
      const raw = {};
      new FormData(this).forEach((v, k) => raw[k] = v);
      this.querySelectorAll('input[type=checkbox]').forEach(cb => {
        raw[cb.name] = cb.checked ? 'completed' : 'incomplete';
      });
      try {
        const res = await fetch(window.location.pathname, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(raw)
        });
        const html = await res.text();
        document.body.innerHTML = html;
      } catch(err) {
        btn.textContent = 'Error — please try again';
        btn.disabled = false;
      }
    });`;
}

