};

const bdg = (text, bg, color) =>
  `<span style="background:${bg};color:${color};padding:3px 9px;border-radius:10px;font-size:11px;font-weight:700;white-space:nowrap">${esc(String(text))}</span>`;

const tick = v => v ? '✅' : '⏳';

const days = v => {
  if (!v) return null;
  return Math.round((Date.now() - new Date(v).getTime()) / 86400000);
};

// ── AGGREGATES FROM table_29 (for Overview + Cohort Progress) ───────────────────
const totalPairs     = pairs.length;
const currentQ       = pairs[0]?.current_quarter || 1;
const currentW       = pairs[0]?.current_week || 1;
const cohortName     = pairs[0]?.cohort_name || '';
const confirmedPairs = pairs.filter(p => p.meeting_confirmed_mentee && p.meeting_confirmed_mentor).length;
const escalatedPairs = pairs.filter(p => parseInt(p.escalation_count||0) > 0).length;
const fbMenteeAny    = pairs.filter(p => parseInt(p.mentee_feedback_count||0) > 0).length;
const goalsSet       = pairs.filter(p => {
  const g = typeof p.mentee_goal === 'string' ? JSON.parse(p.mentee_goal||'null') : p.mentee_goal;
  return g && g.goal_1;
}).length;
const supportPlansDone = pairs.filter(p => {
  const s = typeof p.mentor_support_plan === 'string' ? JSON.parse(p.mentor_support_plan||'null') : p.mentor_support_plan;
  return s && s.additional_context;
}).length;

// ── MENTOR AGGREGATES FROM table_30 ────────────────────────────────────────
const pairsByMentorEmail = {};
for (const p of pairs) {
  if (!p.mentor_email) continue;
  if (!pairsByMentorEmail[p.mentor_email]) pairsByMentorEmail[p.mentor_email] = [];
  pairsByMentorEmail[p.mentor_email].push(p);
}
const mentorsWithEsc     = allMentors.filter(m => parseInt(m.total_escalations||0) > 0).length;
const mentorsAllConfirmed = allMentors.filter(m => {
  const mPairs = pairsByMentorEmail[m.email] || [];
  return mPairs.length > 0 && mPairs.every(p => p.meeting_confirmed_mentor);
}).length;

// ── FUNNEL BAR ────────────────────────────────────────────────────────────────
const fPct = n => totalPairs > 0 ? Math.round((n / totalPairs) * 100) : 0;
const fBar = (label, n, color) => `
  <div style="display:flex;align-items:center;gap:12px;margin-bottom:10px">
    <div style="width:180px;font-size:13px;color:#374151;flex-shrink:0">${label}</div>
    <div style="flex:1;background:#E5E7EB;border-radius:4px;height:12px;overflow:hidden">
      <div style="width:${fPct(n)}%;height:12px;background:${color};border-radius:4px"></div>
    </div>
    <div style="width:70px;text-align:right;font-size:13px;font-weight:600;color:#374151">
      ${n} <span style="font-weight:400;color:#9CA3AF;font-size:11px">(${fPct(n)}%)</span>
    </div>
  </div>`;

// ── TAB 1: PAIRS ──────────────────────────────────────────────────────────────
const hasPending   = parseInt(metrics.pending_pairs) > 0;
const nextCohort   = esc(metrics.next_cohort_name || '');
const launchBanner = hasPending ? `
  <div style="background:#FEF3C7;border:1px solid #F59E0B;border-radius:10px;padding:16px 20px;margin-bottom:20px;display:flex;align-items:center;justify-content:space-between">
    <div>
      <div style="font-weight:700;color:#92400E;font-size:14px">🚀 ${nextCohort} — ${metrics.next_cohort_pending_pairs} pairs ready to launch</div>
      <div style="font-size:12px;color:#92400E;margin-top:2px">All pending pairs are waiting for cohort launch.</div>
    </div>
    <button onclick="launchCohort('${nextCohort}')" style="background:#E8671A;color:white;border:none;padding:10px 24px;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer">Start Cohort →</button>
  </div>` : '';

const pairRows = pairs.map((p, idx) => {
  const cs = p.cycle_status || (p.pair_status === 'pending' ? 'pending-pair' : 'no_cycle');
  const s  = SS[cs] || SS.no_cycle;
  const esc_count = parseInt(p.escalation_count || 0);
  const lastD = days(p.last_activity_at);

  return `
  <tr style="cursor:pointer" onclick="toggleRow('pr-${idx}',this)">
    <td style="padding:11px 14px">
      <div style="font-weight:600;font-size:13px">${esc(p.mentee_name)}</div>
      <div style="font-size:11px;color:#9CA3AF">${esc(p.mentee_email)}</div>
    </td>
