    </td>
    <td style="padding:11px 14px;text-align:center">${bdg('Q'+p.current_quarter+' W'+p.current_week,'#EFF6FF','#1d4ed8')}</td>
    <td style="padding:11px 14px;text-align:center">
      ${bdg(s.label, s.bg, s.color)}
      ${esc_count > 0 ? '<br><span style="display:inline-block;margin-top:3px">'+bdg(esc_count+' escalation'+(esc_count>1?'s':''),'#fee2e2','#991b1b')+'</span>' : ''}
    </td>
