    <td style="padding:11px 14px;text-align:center;color:#9CA3AF;font-size:16px">›</td>
  </tr>
  <tr id="pr-${idx}" style="display:none;background:#FAFAFA">
    <td colspan="7" style="padding:14px 20px">
      <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px">
        <div style="background:white;border:1px solid #E5E7EB;border-radius:8px;padding:10px 14px">
          <div style="font-size:11px;color:#9CA3AF;margin-bottom:3px">Cycle status</div>
          ${bdg(s.label, s.bg, s.color)}
