    </td>
  </tr>`;
}).join('');

// ── TAB 2: OVERVIEW ───────────────────────────────────────────────────────────
const cyclesPerQ = [1,2,3,4].map(q => {
  const done = pairs.filter(p => {
    let cycles = [];
    try { cycles = typeof p.all_cycles === 'string' ? JSON.parse(p.all_cycles||'[]') : (p.all_cycles||[]); } catch(e){}
    const c = cycles.find(c => parseInt(c.quarter) === q);
    return c && (c.status === 'confirmed' || c.status === 'feedback_sent' || c.status === 'completed');
  }).length;
  const esc_q = pairs.filter(p => {
    let cycles = [];
    try { cycles = typeof p.all_cycles === 'string' ? JSON.parse(p.all_cycles||'[]') : (p.all_cycles||[]); } catch(e){}
    const c = cycles.find(c => parseInt(c.quarter) === q);
    return c && c.status === 'escalated';
  }).length;
  const pend_q = pairs.filter(p => {
    let cycles = [];
    try { cycles = typeof p.all_cycles === 'string' ? JSON.parse(p.all_cycles||'[]') : (p.all_cycles||[]); } catch(e){}
    const c = cycles.find(c => parseInt(c.quarter) === q);
    return c && c.status === 'pending';
  }).length;
  return { q, done, esc_q, pend_q };
});

// ── TAB 3: MENTOR ANALYSIS (uses allMentors + pairsByMentorEmail) ─────────────
const showQ4col = parseInt(currentQ) === 4;

const mentorRows = allMentors.map((m, idx) => {
