    const pEsc = parseInt(p.escalation_count||0);
    const sp  = (() => { try { return typeof p.mentor_support_plan === 'string' ? JSON.parse(p.mentor_support_plan||'null') : p.mentor_support_plan; } catch(e){ return null; } })();
    const spText = sp?.additional_context
      ? `<div style="font-size:11px;color:#6B7280;margin-top:4px;font-style:italic">"${esc(sp.additional_context.substring(0,120))}${sp.additional_context.length>120?'…':''}"</div>`
      : '<div style="font-size:11px;color:#9CA3AF;margin-top:2px">No support plan submitted</div>';
    return `
    <div style="padding:10px 0;border-bottom:1px solid #F3F4F6">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:4px">
        <div>
          <span style="font-size:13px;font-weight:600">${esc(p.mentee_name)}</span>
          <span style="font-size:11px;color:#9CA3AF;margin-left:6px">${esc(p.mentee_email)}</span>
        </div>
        <div style="display:flex;align-items:center;gap:8px">
          ${bdg(s.label, s.bg, s.color)}
          <span style="font-size:12px">Mtg: ${tick(p.meeting_confirmed_mentor)}</span>
          ${pEsc > 0 ? `<span style="font-size:11px;font-weight:700;color:#991b1b">${pEsc} esc</span>` : ''}
        </div>
      </div>
      ${spText}
    </div>`;
  }).join('')
  : '<div style="font-size:12px;color:#9CA3AF;padding:8px 0">No mentees assigned this cohort</div>';

  return `
  <tr style="cursor:pointer" onclick="toggleRow('mr-${idx}',this)">
    <td style="padding:11px 14px">
      <div style="font-weight:600;font-size:13px">${esc(m.name)}</div>
      <div style="font-size:11px;color:#9CA3AF">${esc(m.email)}</div>
    </td>
    <td style="padding:11px 14px;text-align:center;font-weight:600;color:${total===0?'#9CA3AF':'#374151'}">${total}</td>
    <td style="padding:11px 14px;text-align:center">
      ${total > 0 ? `<span style="font-weight:600;color:${confMtg===total?'#166534':confMtg===0?'#991b1b':'#92400E'}">${confMtg} / ${total}</span>` : '<span style="color:#9CA3AF">—</span>'}
    </td>
    <td style="padding:11px 14px;text-align:center">
      ${total > 0 ? `<span style="font-weight:600;color:${spDone===total?'#166534':'#92400E'}">${spDone} / ${total}</span>` : '<span style="color:#9CA3AF">—</span>'}
    </td>
