    <td style="padding:11px 14px;text-align:center;font-weight:600;color:${totalEsc>0?'#991b1b':'#374151'}">${totalEsc}</td>
    <td style="padding:11px 14px;text-align:center">${statusLabel}</td>
    <td style="padding:11px 14px;text-align:center;color:#9CA3AF;font-size:16px">›</td>
