    </td>
  </tr>`;
}).join('');

// ── TAB 4: MENTEE ANALYSIS (uses allMentees) ──────────────────────────────────
const menteeRows = allMentees.map((p, idx) => {
  const mg = (() => { try { return typeof p.mentee_goal === 'string' ? JSON.parse(p.mentee_goal||'null') : p.mentee_goal; } catch(e){ return null; } })();
  const sp = (() => { try { return typeof p.mentor_support_plan === 'string' ? JSON.parse(p.mentor_support_plan||'null') : p.mentor_support_plan; } catch(e){ return null; } })();
  const completedDetail = (() => { try { return typeof p.goals_completed_detail === 'string' ? JSON.parse(p.goals_completed_detail||'[]') : (p.goals_completed_detail||[]); } catch(e){ return []; } })();
  const allCycles = (() => { try { return typeof p.all_cycles === 'string' ? JSON.parse(p.all_cycles||'[]') : (p.all_cycles||[]); } catch(e){ return []; } })();

  const isPaired    = !!p.pair_id;
  const goalCount   = mg ? [mg.goal_1, mg.goal_2, mg.goal_3].filter(Boolean).length : 0;
  const goalsComp   = parseInt(p.goals_completed_count||0);
  const mFb         = parseInt(p.mentee_feedback_count||0);
  const llCount     = parseInt(p.learning_logs_count||0);
  const escCount    = parseInt(p.escalation_count||0);
  const lastAct     = days(p.last_activity_at);
  const qDisplay    = p.current_quarter ? 'Q'+p.current_quarter+' W'+p.current_week : '—';

  let engLabel, engBg, engColor;
  if (!isPaired) {
    engLabel='Unpaired'; engBg='#F3F4F6'; engColor='#6B7280';
  } else if (escCount >= 2 || (lastAct !== null && lastAct > 60 && !p.meeting_confirmed_mentee)) {
    engLabel='At risk'; engBg='#fee2e2'; engColor='#991b1b';
  } else if (p.meeting_confirmed_mentee && mFb > 0 && goalCount > 0) {
    engLabel='Strong'; engBg='#dcfce7'; engColor='#166534';
  } else if (p.meeting_confirmed_mentee || goalCount > 0) {
    engLabel='Moderate'; engBg='#FEF3C7'; engColor='#92400E';
  } else {
    engLabel='Low'; engBg='#F3F4F6'; engColor='#6B7280';
  }

  const goalsHtml = mg && mg.goal_1 ? [
    mg.goal_1 ? `<div style="padding:4px 0;border-bottom:1px solid #F3F4F6"><span style="font-size:11px;color:#9CA3AF">Goal 1:</span> <span style="font-size:12px;color:#374151">${esc(mg.goal_1)}</span></div>` : '',
    mg.goal_2 ? `<div style="padding:4px 0;border-bottom:1px solid #F3F4F6"><span style="font-size:11px;color:#9CA3AF">Goal 2:</span> <span style="font-size:12px;color:#374151">${esc(mg.goal_2)}</span></div>` : '',
    mg.goal_3 ? `<div style="padding:4px 0"><span style="font-size:11px;color:#9CA3AF">Goal 3:</span> <span style="font-size:12px;color:#374151">${esc(mg.goal_3)}</span></div>` : '',
    mg.additional_context ? `<div style="padding:4px 0;margin-top:4px;border-top:1px solid #E5E7EB"><span style="font-size:11px;color:#9CA3AF">Context:</span> <span style="font-size:12px;color:#374151;font-style:italic">${esc(mg.additional_context)}</span></div>` : ''
  ].filter(Boolean).join('')
  : '<span style="font-size:12px;color:#9CA3AF">No goals submitted</span>';

  const spHtml = sp?.additional_context
    ? `<div style="font-size:12px;color:#374151;font-style:italic;line-height:1.5">"${esc(sp.additional_context.substring(0,200))}${sp.additional_context.length>200?'…':''}"</div>`
    : '<span style="font-size:12px;color:#9CA3AF">No support plan submitted</span>';

  const qTimeline = isPaired ? [1,2,3,4].map(q => {
    const c = allCycles.find(c => parseInt(c.quarter) === q);
    if (!c) {
      const isFuture = q > parseInt(p.current_quarter||1);
      return `<div style="padding:5px 0;font-size:12px;color:${isFuture?'#9CA3AF':'#374151'}">Q${q}: ${isFuture ? 'Upcoming' : 'No cycle created'}</div>`;
