    return `<div style="display:flex;align-items:center;justify-content:space-between;padding:5px 0;border-bottom:1px solid #F3F4F6;font-size:12px">
      <span style="font-weight:600;color:#374151;width:24px">Q${q}</span>
      <span>${bdg(cs2.label, cs2.bg, cs2.color)}</span>
      <span style="color:#374151">Mentee ${c.meeting_confirmed_mentee?'✅':'⏳'} · Mentor ${c.meeting_confirmed_mentor?'✅':'⏳'}</span>
      <span style="color:#9CA3AF">${c.meeting_confirmed_at ? new Date(c.meeting_confirmed_at).toLocaleDateString('en-GB') : '—'}</span>
    </div>`;
  }).join('') : '<div style="font-size:12px;color:#9CA3AF">Not yet paired — no cycle history</div>';

  const compHtml = completedDetail.length > 0
    ? completedDetail.map(gc => `<span style="font-size:11px;background:#dcfce7;color:#166534;padding:2px 8px;border-radius:8px;margin:2px;display:inline-block">Q${gc.quarter} Goal ${gc.goal_index} ✓</span>`).join('')
    : '<span style="font-size:12px;color:#9CA3AF">No goals marked complete yet</span>';

  return `
  <tr style="cursor:pointer" onclick="toggleRow('ee-${idx}',this)">
    <td style="padding:11px 14px">
      <div style="font-weight:600;font-size:13px">${esc(p.name)}</div>
      <div style="font-size:11px;color:#9CA3AF">${esc(p.email)}</div>
    </td>
    <td style="padding:11px 14px;font-size:13px;color:${isPaired?'#374151':'#9CA3AF'}">${isPaired ? esc(p.mentor_name) : 'Not paired'}</td>
    <td style="padding:11px 14px;text-align:center">${isPaired ? bdg(qDisplay,'#EFF6FF','#1d4ed8') : '<span style="color:#9CA3AF">—</span>'}</td>
    <td style="padding:11px 14px;text-align:center">
      <span style="font-weight:600;color:${goalCount>0?'#166534':'#9CA3AF'}">${goalCount}/3 set</span><br>
      <span style="font-size:11px;color:${goalsComp>0?'#166534':'#9CA3AF'}">${goalsComp} completed</span>
    </td>
    <td style="padding:11px 14px;text-align:center">${isPaired ? tick(p.meeting_confirmed_mentee) : '<span style="color:#9CA3AF">—</span>'}</td>
    <td style="padding:11px 14px;text-align:center">
      <span style="font-weight:600;color:${mFb>0?'#2563EB':'#9CA3AF'}">${mFb}</span>
      <span style="font-size:11px;color:#9CA3AF"> submitted</span>
    </td>
    <td style="padding:11px 14px;text-align:center">
      <span style="font-weight:600;color:${llCount>0?'#2563EB':'#9CA3AF'}">${llCount}</span>
    </td>
    <td style="padding:11px 14px;text-align:center;font-weight:600;color:${escCount>0?'#991b1b':'#374151'}">${escCount}</td>
    <td style="padding:11px 14px;text-align:center">
      <span style="font-size:11px;color:${lastAct!==null&&lastAct>30?'#991b1b':'#9CA3AF'}">${lastAct !== null ? lastAct+'d ago' : '—'}</span>
    </td>
    <td style="padding:11px 14px;text-align:center">${bdg(engLabel, engBg, engColor)}</td>
    <td style="padding:11px 14px;text-align:center;color:#9CA3AF;font-size:16px">›</td>
  </tr>
  <tr id="ee-${idx}" style="display:none;background:#FAFAFA">
    <td colspan="11" style="padding:16px 20px">
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:14px">
        <div>
          <div style="font-size:11px;font-weight:700;color:#9CA3AF;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:8px">Goals set — Q${mg?.quarter||p.current_quarter||'—'}</div>
          ${goalsHtml}
        </div>
        <div>
          <div style="font-size:11px;font-weight:700;color:#9CA3AF;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:8px">Mentor support plan</div>
          ${spHtml}
        </div>
      </div>
      <div style="margin-bottom:14px">
        <div style="font-size:11px;font-weight:700;color:#9CA3AF;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:8px">Quarter history</div>
        ${qTimeline}
      </div>
      <div>
        <div style="font-size:11px;font-weight:700;color:#9CA3AF;text-transform:uppercase;letter-spacing:0.4px;margin-bottom:6px">Goals completed all time</div>
        ${compHtml}
      </div>
      ${escCount >= 2 ? `<div style="margin-top:10px;padding:8px 12px;background:#fff5f5;border-left:3px solid #dc2626;border-radius:0 6px 6px 0;font-size:12px;color:#991b1b">⚠ ${escCount} escalations — recommend direct HR contact with ${esc(p.name)}.</div>` : ''}
    </td>
  </tr>`;
}).join('');

// ── TAB 5: COHORT PROGRESS ────────────────────────────────────────────────────
const qBars = cyclesPerQ.map(({ q, done, esc_q, pend_q }) => {
  const isUpcoming = q > parseInt(currentQ);
  const isCurrent  = q === parseInt(currentQ);
  const donePct = fPct(done);
  const pendPct = fPct(pend_q);
