    results.push({ json: { ...d, _completion_type: 'graduation' } });

  } else if (quarter < 4) {
    // Q1/Q2/Q3 and both parties have now confirmed — mark cycle confirmed
    results.push({ json: { ...d, _completion_type: 'cycle_confirmed' } });
  }
}

